use std::quantum::{init0,h,t,tdg,z,phase_eighth,unit,finish,join,split};
use std::observe::measure_z;
observe fn ideal(pair:Q<(Bit,Bit)>)->(Bit,Q<Bit>){let(q,r)=split(pair);(measure_z(q),r)}
observe fn actual(pair:Q<(Bit,Bit)>)->(Bit,Q<Bit>){let(q,r)=split(pair);(measure_z(t(q)),r)}
pub observe fn f(pair:Q<(Bit,Bit)>)->(Bit,Q<Bit>){apply_contract(actual,ideal,pair)}
pub observe fn main()->(Bit,Bit){let(b,r)=f(join(h(init0()),h(init0())));(b,measure_z(h(r)))}

